import base64
import bisect
import json


def encode_cursor(record):
    payload = json.dumps([record["created_at"], record["id"]]).encode()
    return base64.urlsafe_b64encode(payload).decode()


def decode_cursor(cursor):
    """The (created_at, id) a cursor stands for; ValueError if it is not one we could have made."""
    try:
        position = json.loads(base64.urlsafe_b64decode(cursor))
    except (ValueError, TypeError) as error:          # bad base64, bad UTF-8, bad JSON, not even text
        raise ValueError(f"invalid cursor: {cursor!r}") from error
    is_number = lambda value: isinstance(value, (int, float)) and not isinstance(value, bool)
    if not (isinstance(position, list) and len(position) == 2 and all(map(is_number, position))):
        raise ValueError(f"invalid cursor: {cursor!r}")
    return tuple(position)


def get_page(records, limit, cursor=None):
    start = 0
    if cursor is not None:
        after = decode_cursor(cursor)
        # the list is sorted by this key, so the first record after the cursor is found by binary search
        start = bisect.bisect_right(records, after, key=lambda record: (record["created_at"], record["id"]))
    items = records[start:start + limit]
    has_more = start + limit < len(records)
    return items, (encode_cursor(items[-1]) if has_more else None)
